// Generated by AI, edited by humans
import { REGIONS_META, type RegionMeta } from './download_meta'
import { ZipWriter, Uint8ArrayReader } from '@zip.js/zip.js'
import { waitForPageReady } from '../scripts/page_ready'
import { ElasticSlider, ElasticRangeSlider } from './slider'
import { CustomSelect } from './custom_select'

// Average wallpaper image size injected at build time into window.__AVG_IMAGE_SIZE_BYTES__
declare global {
    interface Window {
        __AVG_IMAGE_SIZE_BYTES__?: number
    }
}
function getAvgImageSizeBytes(): number {
    return window.__AVG_IMAGE_SIZE_BYTES__ || 0
}

function formatFileSize(bytes: number): string {
    const kb = bytes / 1024
    const mb = kb / 1024
    const gb = mb / 1024

    if (gb >= 1) {
        return `${gb.toFixed(1)}\u202FGB`
    }
    if (mb >= 1) {
        const valStr = mb >= 100 ? `${Math.round(mb)}` : mb.toFixed(1)
        return `${valStr}\u202FMB`
    }
    if (kb >= 1) {
        const valStr = kb >= 100 ? `${Math.round(kb)}` : kb.toFixed(1)
        return `${valStr}\u202FKB`
    }
    return `${bytes}\u202FB`
}
const STORAGE_KEY_PREFIX = 'bwa_download_'

function loadSetting(key: string, defaultValue: string): string {
    try {
        const val = localStorage.getItem(STORAGE_KEY_PREFIX + key)
        return val !== null ? val : defaultValue
    } catch {
        return defaultValue
    }
}

function saveSetting(key: string, value: string): void {
    try {
        localStorage.setItem(STORAGE_KEY_PREFIX + key, value)
    } catch {}
}

function setupStickyHeaderShadow(): void {
    const topBar = document.getElementById('download_top_bar')
    const firstContentBlock = document.querySelector<HTMLElement>('#download_content > :first-child')
    if (!topBar || !firstContentBlock) {
        return
    }

    const updateHeaderHeight = (): void => {
        const height = topBar.offsetHeight
        document.documentElement.style.setProperty('--top-bar-height', `${height}px`)
    }

    const updateShadow = (): void => {
        const topBarBottom = topBar.getBoundingClientRect().bottom
        const contentTop = firstContentBlock.getBoundingClientRect().top
        topBar.classList.toggle('has-shadow', contentTop <= topBarBottom)
    }

    window.addEventListener('scroll', updateShadow, { passive: true })
    window.addEventListener('resize', () => {
        updateHeaderHeight()
        updateShadow()
    }, { passive: true })

    updateHeaderHeight()
    updateShadow()
}

interface ImageMetadata {
    date: string
    url: string
    title?: string
    market?: string
}

// DOM Elements
const regionsGrid = document.getElementById('regions_grid') as HTMLElement
const dateRangeSliderContainer = document.getElementById('date_range_slider') as HTMLElement
const startDateInput = document.getElementById('start_date_badge') as HTMLInputElement
const endDateInput = document.getElementById('end_date_badge') as HTMLInputElement
const summaryCount = document.getElementById('summary_count') as HTMLElement
const compressionSliderContainer = document.getElementById('compression_slider_container') as HTMLElement
const startBtn = document.getElementById('start_btn') as HTMLButtonElement
const startBtnText = document.getElementById('start_btn_text') as HTMLElement
const cancelBtn = document.getElementById('cancel_btn') as HTMLButtonElement
const progressPanel = document.getElementById('progress_panel') as HTMLElement
const progressStatus = document.getElementById('progress_status') as HTMLElement
const progressPercentage = document.getElementById('progress_percentage') as HTMLElement
const progressFill = document.getElementById('progress_fill') as HTMLElement
const progressItems = document.getElementById('progress_items') as HTMLElement
const progressBytes = document.getElementById('progress_bytes') as HTMLElement

// State
let selectedRegions: Set<string> = new Set()
let minGlobalDate = new Date('2010-01-01')
let maxGlobalDate = new Date()
let isDownloading = false
let abortController: AbortController | null = null

// Sliders instances
let dateRangeSlider: ElasticRangeSlider
let compressionSlider: ElasticSlider

// Helper: Format Date YYYY-MM-DD
function formatDate(d: Date): string {
    const y = d.getFullYear()
    const m = String(d.getMonth() + 1).padStart(2, '0')
    const day = String(d.getDate()).padStart(2, '0')
    return `${y}-${m}-${day}`
}

function parseDate(s: string): Date {
    const [y, m, d] = s.split('-').map(Number)
    return new Date(y, m - 1, d)
}

function parseFuzzyDate(input: string, isStart: boolean): Date | null {
    const trimmed = input.trim()
    if (!trimmed) return null

    // Pattern 1: Just year, e.g. "2020" or "20"
    const yearMatch = trimmed.match(/^(\d{4})$/)
    if (yearMatch) {
        const year = parseInt(yearMatch[1], 10)
        return isStart ? new Date(year, 0, 1) : new Date(year, 11, 31)
    }

    // Pattern 2: Year and month, e.g. "2020-05", "2020/05", "2020.05"
    const yearMonthMatch = trimmed.match(/^(\d{4})[-/.](0?[1-9]|1[0-2])$/)
    if (yearMonthMatch) {
        const year = parseInt(yearMonthMatch[1], 10)
        const month = parseInt(yearMonthMatch[2], 10)
        if (isStart) {
            return new Date(year, month - 1, 1)
        } else {
            // Day 0 of next month is the last day of current month
            return new Date(year, month, 0)
        }
    }

    // Pattern 3: Full date, e.g. "2020-05-15", "2020/05/15", "2020.05.15"
    const fullDateMatch = trimmed.match(/^(\d{4})[-/.](0?[1-9]|1[0-2])[-/.](0?[1-9]|[12]\d|3[01])$/)
    if (fullDateMatch) {
        const year = parseInt(fullDateMatch[1], 10)
        const month = parseInt(fullDateMatch[2], 10)
        const day = parseInt(fullDateMatch[3], 10)
        const d = new Date(year, month - 1, day)
        // Verify valid day for month
        if (d.getFullYear() === year && d.getMonth() === month - 1 && d.getDate() === day) {
            return d
        }
    }

    return null
}

function daysBetween(d1: Date, d2: Date): number {
    const diff = Math.abs(d2.getTime() - d1.getTime())
    return Math.round(diff / (1000 * 60 * 60 * 24))
}

function addDays(d: Date, days: number): Date {
    const res = new Date(d)
    res.setDate(res.getDate() + days)
    return res
}

// Populate regions grid with toggle buttons
function initRegions() {
    let overallMin = parseDate(REGIONS_META[0].minDate)
    let overallMax = parseDate(REGIONS_META[0].maxDate)

    REGIONS_META.forEach(reg => {
        const rMin = parseDate(reg.minDate)
        const rMax = parseDate(reg.maxDate)
        if (rMin < overallMin) overallMin = rMin
        if (rMax > overallMax) overallMax = rMax
    })

    minGlobalDate = overallMin
    maxGlobalDate = overallMax

    // Create buttons for each region
    REGIONS_META.forEach(reg => {
        const btn = createRegionChip(reg.id, reg.name, reg.flag, reg.id)
        regionsGrid.appendChild(btn)
    })
}

function createRegionChip(id: string, name: string, flag: string, code?: string): HTMLButtonElement {
    const btn = document.createElement('button')
    btn.type = 'button'
    btn.className = 'region-chip' + (id === 'ROW-en' ? ' region-chip-full-width' : '')
    btn.dataset.regionId = id

    btn.innerHTML = `
        <span class="region-chip-flag">${flag}</span>
        <span class="region-chip-name">${name}</span>
        ${code ? `<span class="region-chip-code">${code}</span>` : ''}
    `

    btn.addEventListener('click', () => {
        toggleRegion(id)
    })

    return btn
}

function toggleRegion(id: string) {
    if (selectedRegions.has(id)) {
        selectedRegions.delete(id)
    } else {
        selectedRegions.add(id)
    }

    saveSetting('regions', JSON.stringify(Array.from(selectedRegions)))
    updateRegionUI()
    updateSliderBounds(true)
}

function updateRegionUI() {
    const chips = regionsGrid.querySelectorAll<HTMLButtonElement>('.region-chip')
    chips.forEach(chip => {
        const id = chip.dataset.regionId
        chip.classList.toggle('active', !!id && selectedRegions.has(id))
    })
}

// Get active min/max date according to region selected
function getActiveDateBounds(): { min: Date; max: Date } {
    if (selectedRegions.size === 0) {
        return { min: minGlobalDate, max: maxGlobalDate }
    }

    let minDate: Date | null = null
    let maxDate: Date | null = null

    REGIONS_META.forEach(reg => {
        if (selectedRegions.has(reg.id)) {
            const rMin = parseDate(reg.minDate)
            const rMax = parseDate(reg.maxDate)
            if (!minDate || rMin < minDate) minDate = rMin
            if (!maxDate || rMax > maxDate) maxDate = rMax
        }
    })

    return {
        min: minDate || minGlobalDate,
        max: maxDate || maxGlobalDate
    }
}

function updateSliderBounds(keepRelative = false) {
    const bounds = getActiveDateBounds()
    const totalDays = Math.max(1, daysBetween(bounds.min, bounds.max))
    dateRangeSlider.setBounds(0, totalDays, keepRelative)
    renderDateRangeUI()
}

function getSelectedDateRange(): { start: Date; end: Date } {
    const bounds = getActiveDateBounds()
    const range = dateRangeSlider.getRange()
    const start = addDays(bounds.min, range.start)
    const end = addDays(bounds.min, range.end)
    return { start, end }
}

function setDateRange(start: Date, end: Date) {
    const bounds = getActiveDateBounds()
    const clampedStart = new Date(Math.max(bounds.min.getTime(), Math.min(bounds.max.getTime(), start.getTime())))
    const clampedEnd = new Date(Math.max(bounds.min.getTime(), Math.min(bounds.max.getTime(), end.getTime())))

    const valStart = daysBetween(bounds.min, clampedStart)
    const valEnd = daysBetween(bounds.min, clampedEnd)

    dateRangeSlider.setRange(valStart, valEnd)
    renderDateRangeUI()
}

function renderDateRangeUI() {
    const { start, end } = getSelectedDateRange()
    if (document.activeElement !== startDateInput) {
        startDateInput.value = formatDate(start)
    }
    if (document.activeElement !== endDateInput) {
        endDateInput.value = formatDate(end)
    }
    updateEstimateSummary()
}

function updateEstimateSummary() {
    const { start, end } = getSelectedDateRange()
    const startStr = formatDate(start)
    const endStr = formatDate(end)

    let countEstimate = 0

    REGIONS_META.forEach(reg => {
        if (selectedRegions.has(reg.id)) {
            if (reg.minDate <= endStr && reg.maxDate >= startStr) {
                const s = reg.minDate > startStr ? parseDate(reg.minDate) : start
                const e = reg.maxDate < endStr ? parseDate(reg.maxDate) : end
                if (s <= e) {
                    countEstimate += daysBetween(s, e) + 1
                }
            }
        }
    })

    const estBytes = countEstimate * getAvgImageSizeBytes()
    const sizeStr = countEstimate === 0 ? '~0\u202FMB' : `~${formatFileSize(estBytes)}`

    summaryCount.innerHTML = `${countEstimate.toLocaleString()} <span>wallpapers (${sizeStr})</span>`
    startBtn.disabled = countEstimate === 0
}

// Fetch helper
async function fetchMetadataForRange(
    regionId: string,
    startYear: number,
    endYear: number,
    signal: AbortSignal,
    onProgress: (status: string) => void
): Promise<ImageMetadata[]> {
    const results: ImageMetadata[] = []

    for (let y = startYear; y <= endYear; y++) {
        if (signal.aborted) break
        const url = `/${regionId}.${y}.json`
        onProgress(`Fetching API metadata for ${regionId} (${y})...`)

        try {
            const resp = await fetch(url, { signal })
            if (resp.ok) {
                const list = await resp.json()
                if (Array.isArray(list)) {
                    for (const item of list) {
                        if (item.url && item.date) {
                            results.push({
                                date: item.date,
                                url: item.url,
                                title: item.title,
                                market: regionId
                            })
                        }
                    }
                }
            }
        } catch (err: any) {
            if (err.name === 'AbortError') throw err
            console.warn(`Could not load ${url}:`, err)
        }
    }

    return results
}

// Low-RAM ZIP Streaming Downloader
async function runStreamingDownload() {
    if (isDownloading) return

    if (selectedRegions.size === 0) {
        return
    }

    const { start, end } = getSelectedDateRange()
    const startStr = formatDate(start)
    const endStr = formatDate(end)
    const compressionLevel = compressionSlider.getValue()

    isDownloading = true
    abortController = new AbortController()
    const signal = abortController.signal

    // UI Updates
    startBtn.disabled = true
    cancelBtn.style.display = 'inline-block'
    progressPanel.style.display = 'flex'
    progressFill.style.width = '0%'
    progressPercentage.textContent = '0%'
    progressStatus.textContent = 'Gathering metadata...'

    let totalSavedBytes = 0

    try {
        const startYear = start.getFullYear()
        const endYear = end.getFullYear()

        const regionsToFetch = Array.from(selectedRegions)

        let allEntries: ImageMetadata[] = []

        // Step 1: Fetch metadata
        for (const reg of regionsToFetch) {
            if (signal.aborted) break
            const metaList = await fetchMetadataForRange(reg, startYear, endYear, signal, (st) => {
                progressStatus.textContent = st
            })
            for (const item of metaList) {
                if (item.date >= startStr && item.date <= endStr) {
                    allEntries.push(item)
                }
            }
        }

        if (signal.aborted) throw new Error('Download cancelled')

        allEntries.sort((a, b) => a.date.localeCompare(b.date))

        const totalCount = allEntries.length
        if (totalCount === 0) {
            alert('No images found in the selected date range.')
            resetDownloadUI()
            return
        }

        progressStatus.textContent = `Initializing stream for ${totalCount} wallpapers...`
        progressItems.textContent = `0 / ${totalCount} images`

        const regionLabel = selectedRegions.size === REGIONS_META.length
            ? 'ALL'
            : Array.from(selectedRegions).join('_')
        const filename = `BingWallpapers_${regionLabel}_${startStr}_to_${endStr}.zip`

        let fileHandle: any = null
        let writableStream: WritableStream | null = null

        if ('storage' in navigator && typeof navigator.storage.getDirectory === 'function') {
            const root = await navigator.storage.getDirectory()
            fileHandle = await root.getFileHandle(`temp_${Date.now()}.zip`, { create: true })
            writableStream = await fileHandle.createWritable()
        }

        const chunks: Uint8Array[] = []
        if (!writableStream) {
            console.warn('OPFS createWritable not available, using fallback stream chunks')
            writableStream = new WritableStream({
                write(chunk) {
                    chunks.push(chunk)
                    totalSavedBytes += chunk.byteLength
                }
            })
        }

        const zipWriter = new ZipWriter(writableStream, {
            zip64: true,
            level: compressionLevel
        })

        let completed = 0
        const MAX_CONCURRENT_DOWNLOADS = 5
        const MAX_RETRIES = 3
        const RETRY_DELAY_MS = 1000

        interface DownloadTask {
            item: ImageMetadata
            retries: number
        }

        const queue: DownloadTask[] = allEntries.map(item => ({ item, retries: 0 }))
        let queueIndex = 0

        const updateProgressUI = () => {
            const rawPct = (completed / totalCount) * 100
            const pctClamped = Math.min(100, Math.max(0, rawPct))
            const pctInt = Math.floor(pctClamped)
            progressPercentage.textContent = `${pctInt}%`
            progressFill.style.width = `${pctClamped}%`
            progressItems.textContent = `${completed} / ${totalCount} images`
            progressBytes.textContent = `${formatFileSize(totalSavedBytes)} saved`
        }

        // Sequential lock for writing to ZipWriter
        let zipWriteChain: Promise<void> = Promise.resolve()
        let zipWriteError: any = null

        const writeToZipSequentially = (zipPath: string, data: Uint8Array, size: number): Promise<void> => {
            zipWriteChain = zipWriteChain.then(async () => {
                if (signal.aborted || zipWriteError) return
                await zipWriter.add(zipPath, new Uint8ArrayReader(data))
                totalSavedBytes += size
                completed++
                updateProgressUI()
            }).catch(err => {
                console.error('ZIP write error:', err)
                zipWriteError = err
                throw err
            })
            return zipWriteChain
        }

        const waitDelay = (ms: number) => new Promise(res => setTimeout(res, ms))

        // Worker function for parallel downloading
        const worker = async (workerId: number) => {
            while (queueIndex < queue.length && !signal.aborted && !zipWriteError) {
                const task = queue[queueIndex++]
                const item = task.item
                const regionPrefix = item.market || 'ROW-en'
                const zipPath = `${regionPrefix}/${item.date}.jpg`

                progressStatus.textContent = `Downloading (${completed + 1}/${totalCount}): ${item.date}...`

                try {
                    const imgResp = await fetch(item.url, { signal, mode: 'cors' })
                    if (!imgResp.ok) {
                        throw new Error(`HTTP ${imgResp.status}`)
                    }
                    const arrayBuf = await imgResp.arrayBuffer()
                    const data = new Uint8Array(arrayBuf)

                    // Write directly into ZIP under sequential lock (backpressures this worker)
                    await writeToZipSequentially(zipPath, data, data.byteLength)
                } catch (err: any) {
                    if (err.name === 'AbortError' || signal.aborted) {
                        return
                    }
                    if (zipWriteError) {
                        return
                    }
                    if (task.retries < MAX_RETRIES) {
                        task.retries++
                        console.warn(`Worker ${workerId}: Retry ${task.retries}/${MAX_RETRIES} for ${item.url}:`, err)
                        await waitDelay(RETRY_DELAY_MS)
                        // Push back to queue for another attempt
                        queue.push(task)
                    } else {
                        console.error(`Worker ${workerId}: Failed after ${MAX_RETRIES} retries: ${item.url}:`, err)
                        // Count as completed (skipped) so progress finishes
                        completed++
                        updateProgressUI()
                    }
                }
            }
        }

        const workers = Array.from({ length: Math.min(MAX_CONCURRENT_DOWNLOADS, totalCount) }, (_, i) => worker(i + 1))
        await Promise.all(workers)

        // Wait for any remaining write operations in chain
        await zipWriteChain

        if (zipWriteError) throw zipWriteError
        if (signal.aborted) throw new Error('Download cancelled')

        progressStatus.textContent = 'Finalizing ZIP archive...'
        await zipWriter.close()

        progressStatus.textContent = 'Saving archive to downloads...'
        let blobUrl: string
        let tempFileToClean: any = null

        if (fileHandle) {
            const finalFile = await fileHandle.getFile()
            blobUrl = URL.createObjectURL(finalFile)
            tempFileToClean = fileHandle
        } else {
            const blob = new Blob(chunks, { type: 'application/zip' })
            blobUrl = URL.createObjectURL(blob)
        }

        const a = document.createElement('a')
        a.href = blobUrl
        a.download = filename
        document.body.appendChild(a)
        a.click()
        a.remove()

        setTimeout(async () => {
            URL.revokeObjectURL(blobUrl)
            if (tempFileToClean) {
                try {
                    const root = await navigator.storage.getDirectory()
                    await root.removeEntry(tempFileToClean.name)
                } catch {}
            }
        }, 30000)

        progressStatus.textContent = 'Completed!'
        startBtnText.textContent = 'Download Again'

    } catch (err: any) {
        if (err.name === 'AbortError' || err.message === 'Download cancelled') {
            progressStatus.textContent = 'Download cancelled by user.'
        } else {
            console.error('Download error:', err)
            progressStatus.textContent = `Error: ${err.message || 'Download failed'}`
            alert(`Download error: ${err.message}`)
        }
    } finally {
        resetDownloadUI()
    }
}

function resetDownloadUI() {
    isDownloading = false
    cancelBtn.style.display = 'none'
    updateEstimateSummary()
}

// Event Listeners
function setupEvents() {
    // Initialize Elastic Range Slider for Dates
    dateRangeSlider = new ElasticRangeSlider({
        container: dateRangeSliderContainer,
        min: 0,
        max: 1000,
        initialStart: 0,
        initialEnd: 1000,
        onInput: () => renderDateRangeUI(),
        onChange: () => renderDateRangeUI()
    })

    const savedCompression = parseInt(loadSetting('compression', '0'), 10)
    const initialCompression = Number.isNaN(savedCompression) ? 0 : Math.max(0, Math.min(9, savedCompression))

    const singleSliderWrapper = compressionSliderContainer.closest('.single-slider-wrapper') as HTMLElement | null

    compressionSlider = new ElasticSlider({
        container: compressionSliderContainer,
        interactionContainer: singleSliderWrapper || compressionSliderContainer,
        min: 0,
        max: 9,
        step: 1,
        initialValue: initialCompression,
        enableSnapping: true,
        showDots: true,
        minDistanceForDotsPx: 30, // threshold
        onChange: (val) => {
            saveSetting('compression', String(val))
        }
    })

    // Manual date inputs
    const handleDateInputCommit = (isStart: boolean) => {
        const input = isStart ? startDateInput : endDateInput
        const parsed = parseFuzzyDate(input.value.trim(), isStart)
        const bounds = getActiveDateBounds()
        const currentRange = getSelectedDateRange()

        if (!parsed || isNaN(parsed.getTime())) {
            input.value = formatDate(isStart ? currentRange.start : currentRange.end)
            return
        }

        if (isStart) {
            let newStart = parsed
            if (newStart < bounds.min) newStart = bounds.min
            if (newStart > bounds.max) newStart = bounds.max
            let newEnd = currentRange.end
            if (newStart > newEnd) newEnd = newStart
            setDateRange(newStart, newEnd)
        } else {
            let newEnd = parsed
            if (newEnd < bounds.min) newEnd = bounds.min
            if (newEnd > bounds.max) newEnd = bounds.max
            let newStart = currentRange.start
            if (newEnd < newStart) newStart = newEnd
            setDateRange(newStart, newEnd)
        }
        input.value = formatDate(isStart ? getSelectedDateRange().start : getSelectedDateRange().end)
    }

    startDateInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            handleDateInputCommit(true)
            startDateInput.blur()
        }
    })
    startDateInput.addEventListener('blur', () => handleDateInputCommit(true))

    endDateInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            handleDateInputCommit(false)
            endDateInput.blur()
        }
    })
    endDateInput.addEventListener('blur', () => handleDateInputCommit(false))

    // Actions
    startBtn.addEventListener('click', () => void runStreamingDownload())

    cancelBtn.addEventListener('click', () => {
        if (abortController) {
            abortController.abort()
        }
    })
}

// Init
initRegions()

waitForPageReady()
setupStickyHeaderShadow()
setupEvents()

// Restore saved settings & initialize slider bounds
const allRegionIds = REGIONS_META.map(r => r.id)
const savedRegionsRaw = loadSetting('regions', '')
let initialRegions: string[] | null = null

if (savedRegionsRaw) {
    try {
        const parsed = JSON.parse(savedRegionsRaw)
        if (Array.isArray(parsed)) {
            initialRegions = parsed.filter(id => allRegionIds.includes(id))
        }
    } catch {}
}

if (initialRegions === null) {
    // Default to all regions selected only on first visit (when no setting saved)
    initialRegions = [...allRegionIds]
}

selectedRegions = new Set(initialRegions)
updateRegionUI()
updateSliderBounds(false)

